import dataclasses

@dataclasses.dataclass
class StreamingRecognitionConfig:
    encoding: str = "LINEAR16"
    sample_rate_hertz: int = 16000
    language_code: str = "en-US"
    enable_automatic_punctuation: bool = True
    interim_results: bool = True

@dataclasses.dataclass
class AudioChunk:
    content: bytes
    sample_rate_hertz: int
    encoding: str

from google.cloud import speech
from speech_models import StreamingRecognitionConfig

class SpeechClient:
    def __init__(self):
        self.client = speech.SpeechClient()

    def get_streaming_config(self, config: StreamingRecognitionConfig):
        return speech.StreamingRecognitionConfig(
            config=speech.RecognitionConfig(
                encoding=speech.RecognitionConfig.AudioEncoding[config.encoding],
                sample_rate_hertz=config.sample_rate_hertz,
                language_code=config.language_code,
                enable_automatic_punctuation=config.enable_automatic_punctuation,
            ),
            interim_results=config.interim_results,
        )

def handle_partial_results(responses):
    for response in responses:
        if not response.results:
            continue

        result = response.results[0]
        if not result.alternatives:
            continue

        transcript = result.alternatives[0].transcript

        if result.is_final:
            yield {"type": "final", "transcript": transcript, "confidence": result.alternatives[0].confidence}
        else:
            yield {"type": "partial", "transcript": transcript}

from google.cloud import translate_v2 as translate

def translate_caption(text: str, target_language: str) -> dict:
    translate_client = translate.Client()

    result = translate_client.translate(text, target_language=target_language)

    return {
        "translated_text": result['translatedText'],
        "source_language": result['detectedSourceLanguage'],
    }

from google.cloud import language_v1

def check_caption_safety(text: str) -> dict:
    client = language_v1.LanguageServiceClient()

    document = language_v1.Document(content=text, type_=language_v1.Document.Type.PLAIN_TEXT)

    # Classifying text can help identify content that might be unsafe.
    # The categories returned can indicate potential issues.
    response = client.classify_text(request={'document': document})

    safety_analysis = []
    for category in response.categories:
        safety_analysis.append({
            "name": category.name,
            "confidence": category.confidence,
        })

    return {"safety_analysis": safety_analysis}
